import re

_ESCAPES = re.compile(r"(?:%[0-9A-Fa-f]{2})+")


def _decode(text):
    # "+" is a space; an escaped plus (%2B) is decoded below, so it stays a plus
    text = text.replace("+", " ")
    # a run of %XX escapes is the bytes of one or more UTF-8 characters
    return _ESCAPES.sub(lambda m: bytes.fromhex(m.group().replace("%", "")).decode("utf-8", "replace"), text)


def parse_query_string(query):
    params = {}
    for pair in query.split("&"):
        if not pair:
            continue                                  # an empty pair, as in "a=1&&b=2"
        key, _, value = pair.partition("=")           # split at the FIRST "="; no "=" gives an empty value
        params.setdefault(_decode(key), []).append(_decode(value))
    return params
